contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entry performing the test
    function run(bytes32 h, uint256 sendAmount) public payable {
        // must have enough balance to send to c
        require(address(this).balance >= sendAmount);
        // precondition: we will test the behavior when sending exactly 1 ether
        require(sendAmount == 1 ether);

        // call lockInGuess sending the provided amount
        c.lockInGuess{value: sendAmount}(h);

        // Observe whether the guess was recorded by checking whether the stored block number is nonzero.
        // The struct Guess has a public mapping? It's not public, so we cannot access it directly.
        // But we can observe that lockInGuess should set guesses[msg.sender].block = block.number + 1,
        // and therefore calling settle immediately should revert because require(block.number > guesses[msg.sender].block) fails.
        // However, settle will revert if guesses[msg.sender].block == 0, so using a call to settle() as a low-level
        // static observation is not possible. Instead, we can observe that after lockInGuess with 1 ether,
        // calling lockInGuess again should revert due to require(guesses[msg.sender].block == 0).

        // A second lockInGuess call with same sender and same amount must revert if the first recorded the guess.
        // We perform it as an external call and capture the revert boolean via low-level call.
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("lockInGuess(bytes32)", h));

        // The property: after sending exactly 1 ether in the first call, a second lockInGuess (without value) must fail (ok == false).
        // This holds for the original contract P, but in mutant M lockInGuess requires 2 ether and the first call would have reverted,
        // so the second call would succeed (ok == true) because no guess was recorded.
        assert(!ok);
    }

    // allow receiving ETH to fund the test
    receive() external payable {}
}

