        vm.deal(player, 2 ether);
        vm.prank(player);
        // perform the call; it must succeed for admissible inputs (1 ether sent)
        c.lockInGuess{value: 1 ether}(h);

        // Exactly one assertion: in the correct contract, the stored block for this player
        // is strictly greater than the block number at which we observed it (block.number)
        // i.e., reference sets guesses[player].block == block.number + 1, so > block.number
        // We read via the public auto-generated getter for the mapping 'guesses'
        (uint256 storedBlock, ) = getGuessBlockAndGuess(player);
        assertTrue(storedBlock > block.number);
    }

    // helper to read the C.guesses mapping: C defines struct Guess { uint block; bytes32 guess; }
    // but the auto-generated getter for a mapping returns the struct fields in order.
    // We provide this wrapper to satisfy the requirement of reading c through its public surface.
    function getGuessBlockAndGuess(address who) internal returns (uint256, bytes32) {
        // The mapping getter is guesses(address) returns (uint, bytes32) in that order.
        // Call it via low-level staticcall to avoid compile-time type mismatch if C's getter signature differs.
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSignature("guesses(address)", who));
        require(ok, "getter call failed");
        return abi.decode(data, (uint256, bytes32));
    }
}

