pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz parameters: a hash to lock in, and a boolean that decides whether the helper should reenter
    function testFuzz_property(bytes32 hash, bool doReenter) public {
        // keep domain wide: no tight assumes. only ensure the helper can hold funds
        // deploy attacker helper that will call back into c during the lockInGuess call
        Attacker attacker = new Attacker(address(c));

        // fund the attacker so it can pay 1 ether to lockInGuess
        vm.deal(address(attacker), 1 ether);

        // attacker will conditionally reenter during lockInGuess; pass its address as the caller
        vm.prank(address(attacker));
        // perform the call: attacker forwards the call into c.lockInGuess while its fallback may reenter
        attacker.invokeLockInGuess(hash, doReenter);

        // Single assertion: After lockInGuess completed, either stored block is zero or stored guess equals provided hash.
        // This reads c through its public getter for the mapping (auto-generated). We use a try/catch style not needed here
        // because call already happened; read the mapping fields via the auto getters.
        (uint256 storedBlock, bytes32 storedGuess) = getGuess(address(attacker));

        // The correct contract guarantees: storedBlock == 0 || storedGuess == hash
        assertTrue(storedBlock == 0 || storedGuess == hash);
    }

    // helper to read the Guess mapping's fields via the compiler-generated getter signature
    // The mapping is: mapping(address => Guess) guesses; where Guess is (uint block; bytes32 guess)
    function getGuess(address who) internal returns (uint256, bytes32) {
        // auto-generated getter has signature: function guesses(address) public view returns (uint256, bytes32);
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("guesses(address)", who));
        require(ok, "getter call failed");
        return abi.decode(ret, (uint256, bytes32));
    }
}

// Attacker contract: optionally reenters into C.lockInGuess during the external call to c.lockInGuess
contract Attacker {
    address immutable target;
    bytes32 public lastHash;
    bool public reenter;

    constructor(address _target) payable {
        target = _target;
    }

    // Called by test via vm.prank(address(this)) to initiate the sequence
    function invokeLockInGuess(bytes32 hash, bool doReenter) external {
        lastHash = hash;
        reenter = doReenter;
        // make the payable call into C.lockInGuess with 1 ether
        // This will trigger Attacker.receive() if the contract C performs a call back into msg.sender during lockInGuess
        C(target).lockInGuess{value: 1 ether}(hash);
    }

