    function _readGuessBlock(address who) internal returns (bytes32, uint256) {
        // The contract C has mapping(address=>Guess) guesses; where Guess { uint block; bytes32 guess; }
        // The auto-generated getter has signature guesses(address) returning (uint256, bytes32).
        // We call it via low-level call to avoid compiler needing the ABI; but we can call directly since C is imported.
        // Use direct call:
        C.Guess memory g = _getGuess(who);
        return (g.guess, g.block);
    }

    function _getGuess(address who) internal view returns (C.Guess memory) {
        return c.guesses(who);
    }
}

