        // the stored Guess.block for that caller (address(rev)) must be zero in the correct contract.
        // We observe this via the auto-generated public getter for the mapping 'guesses' (struct).
        // The reference implementation always clears the block field; the mutant that clears only after transfer
        // can leave it non-zero when the transfer reverts, so this assertion will fail on the mutant for some inputs.
        (uint256 storedBlock, ) = getGuess(address(rev));
        assertTrue(storedBlock == 0);
    }

    // helper to read the struct fields from the public mapping getter; mapping public getter for struct
    // has a generated function guesses(address) that returns (uint256, bytes32) because struct fields are (uint, bytes32)
    function getGuess(address who) internal returns (uint256, bytes32) {
        // call the auto-generated getter on C; this is allowed by the problem statement
        try c.guesses(who) returns (uint256 b, bytes32 g) {
            return (b, g);
        } catch {
            return (uint256(0), bytes32(0));
        }
    }
}

