        // advance blocks so settle can be called
        vm.roll(block.number + 2);

        // Now call settle from the malicious actor; its receive() will revert when the contract
        // tries to transfer 2 ether back to it (simulating a failing transfer)
        bool ok;
        try mal.doSettle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: in the correct contract, after settle() finishes (whether transfer reverted or not),
        // guesses[mal].block must be zero. We observe that via the public getter for the mapping struct's fields.
        // The contract C has a public mapping 'guesses' returning (uint, bytes32) — use it.
        (uint256 b, ) = c.guesses(address(mal));

