// Minimal malicious actor: locks a guess on C then calls settle; its receive() reverts to simulate failing transfer.
contract MaliciousActor {
    C immutable c;
    constructor(C _c) { c = _c; }
    function lock(bytes32 h) external payable { c.lockInGuess{value: msg.value}(h); }
    function doSettle() external { c.settle(); }
    receive() external payable {
        revert("no receive");
    }
}

// A deployable failing receiver (not used directly but kept minimal as allowed helper)
contract ReceiverBad {
    receive() external payable { revert("bad"); }
}

